/* === GAMEPLAY CONSTANTS === */
const DIR = { L: 0, D: 1, U: 2, R: 3 }; // Direction lane indices (0: Left, 1: Down, 2: Up, 3: Right)

// Base arrow sprite points UP; rotate to face each lane
const DIR_ROT = [-Math.PI / 2, Math.PI, 0, Math.PI / 2]; // Rotation in radians for Left (-90°), Down (180°), Up (0°), Right (90°)
const ARROW_LIGHT = [COL.pL, COL.pD, COL.pU, COL.pR]; // Highlight fill colors per direction lane
const ARROW_DARK = [COL.pLD, COL.pDD, COL.pUD, COL.pRD]; // Highlight border colors per direction lane
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));

const STATE = { SPLASH: -1, TITLE: 0, CHARSEL: 1, SONGSEL: 2, BATTLE: 3, WIN: 4 }; // Game flow states
const state = { v: STATE.SPLASH, t: 0, countdownStart: 0, songDecoded: null, songStart: 0, songEnd: 0, winner: -1 };

const players = [
  { name: 'PLATANUS', sprites: DANCERS[0][1], center: { x: 157, y: 380 }, box: { x: 85, y: 255, w: 145, h: 220 },
    combo: 0, score: 0, arrows: [], notes: [], keys: ['P1_L', 'P1_D', 'P1_U', 'P1_R'],
    dirKeys: [['P1_L', 'P1_4', 'P1_1'], ['P1_D', 'P1_5'], ['P1_U', 'P1_2'], ['P1_R', 'P1_6', 'P1_3']],
    arrowBounce: [0, 0, 0, 0],
    color: 0xff5577, perfect: 0, good: 0, miss: 0, seq: 0, gfx: null,
    poseIdx: 0, pulseDx: 0, pulseDy: 0, pulseT: 0 },
  { name: 'LA PARKA', sprites: DANCERS[1][1], center: { x: 642, y: 400 }, box: { x: 570, y: 255, w: 145, h: 220 },
    combo: 0, score: 0, arrows: [], notes: [], keys: ['P2_L', 'P2_D', 'P2_U', 'P2_R'],
    dirKeys: [['P2_L', 'P2_4', 'P2_1'], ['P2_D', 'P2_5'], ['P2_U', 'P2_2'], ['P2_R', 'P2_6', 'P2_3']],
    arrowBounce: [0, 0, 0, 0],
    color: 0x77dd55, perfect: 0, good: 0, miss: 0, seq: 0, gfx: null,
    poseIdx: 0, pulseDx: 0, pulseDy: 0, pulseT: 0 },
];

// Global runtime game state and visual container references
const G = {
  fxLayer: null, titleLayer: null, winLayer: null, tugGfx: null, splashLayer: null,
  worldLayer: null, hudLayer: null,
  bgGfx: null, stageGfx: null, floorGfx: null,
  playerLayers: [],
  notes: [], notesSpawned: 0, notesTotal: 0,
  bar: 0, barVis: 0, // Tug-of-war bar value (-100 to +100) and smoothly interpolated visual position
  cam: null, uiCam: null, camX: 400, camY: 300, camZ: 1, // Camera tracking coordinates & zoom level
  music: null, lastTurn: -1, turnT: 0, turnTxt: null, // Active music instance, turn tracking, and turn HUD text
  audioStart: 0, songLen: 0, blurred: 0, // Audio start timestamp and song total length in seconds
  difficulty: DEFAULT_DIFFICULTY, // Difficulty setting: 0 = EASY, 1 = MEDIUM, 2 = HARD
  mode: '2p', selSong: 0, charSel: [{cursor: 0, ok: 0}, {cursor: 0, ok: 0}], aiPicking: 0,
};

new Phaser.Game({
  type: Phaser.AUTO, width: W, height: H, parent: 'game-root',
  backgroundColor: '#000000', pixelArt: 1,
  scene: { create, update },
});

function updateStagePlayer(idx, fighterIdx, isInstant = 0) {
  G.charSel[idx].cursor = fighterIdx;
  const f = DANCERS[fighterIdx];
  const p = players[idx];
  
  if (isInstant || !G.titleLayer?.scene) {
    p.name = f[0];
    p.sprites = f[1];
    p.poseIdx = 0;
    const g = G.playerLayers[idx];
    if (g) {
      g.clear();
      dsp(g, f[1][0], 0, 0, true);
    }
  } else {
    p.nextName = f[0];
    p.nextSprites = f[1];
    p.isSlidingOut = 1;
    p.slideTarget = 400;
  }
}

function create() {
  const s = this;
  G.worldLayer = s.add.container(0, 0);
  G.fxLayer = s.add.container(0, 0);
  G.hudLayer = s.add.container(0, 0).setDepth(100);
  G.titleLayer = s.add.container(0, 0).setDepth(200);
  G.winLayer = s.add.container(0, 0).setDepth(200);
  G.splashLayer = s.add.container(0, 0).setDepth(300);

  drawBackground(s);
  drawStage(s);
  drawFloor(s);
  drawPlayer(s, 0);
  drawPlayer(s, 1);
  drawTugBar(s);
  drawArrowGfx(s);
  G.worldLayer.add([G.bgGfx, G.stageGfx, G.floorGfx, G.playerLayers[0], G.playerLayers[1], G.fxLayer]);

  // Two cameras: main zooms/pans on the world, UI cam keeps HUD fixed
  G.cam = s.cameras.main;
  G.uiCam = s.cameras.add(0, 0, W, H);
  G.cam.ignore([G.hudLayer, G.titleLayer, G.winLayer, G.splashLayer]);
  G.uiCam.ignore([G.worldLayer]);

  G.turnTxt = cTxt(s, W / 2, 90, '', 22, '#fff200', 1).setAlpha(0);
  for (let i = 0; i < 2; i++) players[i].comboTxt = cTxt(s, i ? 650 : 150, 46, '', 16, i ? '#77dd55' : '#ff5577', 1);
  G.hudLayer.add([G.tugGfx, ...players[0].arrows, ...players[1].arrows, G.turnTxt, players[0].comboTxt, players[1].comboTxt]);
  G.hudLayer.setVisible(0);

  clearInputs();

  if (SKIP_TO_GAMEPLAY) {
    updateStagePlayer(0, 0);
    updateStagePlayer(1, 1 % DANCERS.length);
    G.pendingStart = 1;
    // menu song
    unpack(SONGS[0].data).then(song => {
      G.midiText = song;
      G.notesSong = decode(song);
      G.pendingStart = 0;
      startBattle();
    });
  } else {
    drawSplashScreen(s);
    unpack(MIDI_SONG_FRUKO_Y_SUS_TESOS).then(song => {
      G.menuMidiText = song;
      startMenuMusic();
    });
  }

  G.blurred = 0;
  const setBlur = (v) => { G.blurred = v; clearInputs(); };
  document.addEventListener('visibilitychange', () => setBlur(document.hidden));
  window.addEventListener('blur', () => setBlur(1));
  window.addEventListener('focus', () => setBlur(0));

  const unlockAudio = () => {
    const ctx = s.sound?.context;
    if (ctx && ctx.state === 'suspended') {
      ctx.resume().catch(() => {});
    }
    startMenuMusic();
  };
  window.addEventListener('pointerdown', unlockAudio);
  window.addEventListener('keydown', unlockAudio);
  s.input.on('pointerdown', unlockAudio);
}

function startMenuMusic() {
  if (state.v === STATE.BATTLE || state.v === STATE.WIN) return;
  if (!G.menuMidiText) return;
  const ctx = G.titleLayer?.scene?.sound?.context;
  if (!ctx) return;
  if (ctx.state === 'suspended') {
    ctx.resume().catch(() => {});
  }
  if (G.menuMusic) return;
  G.menuMusic = playMidi(ctx, G.menuMidiText, (len) => {
    G.menuSongLen = len;
  });
}

/* === DRAWING === */
function drawSplashScreen(s) {
  G.hudLayer.setVisible(0);
  G.titleLayer.setVisible(0);
  G.winLayer.setVisible(0);
  G.splashLayer.removeAll(1);
  G.splashLayer.setVisible(1);

  const bg = s.add.rectangle(W / 2, H / 2, W, H, 0x000, 1);
  const txt = cTxt(s, W / 2, H / 2, '🇨🇴 Platanus hack 26, Bogotá 🇨🇴\n\npresenta', 24, '#fff', 1);
  txt.setAlign('center');
  G.splashLayer.add([bg, txt]);
}

function drawBackground(s) {
  const g = s.add.graphics(), FW = W + 2 * PAD, X0 = -PAD;
  g.setDepth(-100);
  // Sky gradient — deep blue top to pale horizon
  const sky = [0x1a3466, 0x254a82, 0x30609e, 0x4578b8, 0x5c90cc, 0x74a8dd, 0x8ec0ea, 0xa8d6f4];
  const bh = Math.ceil((H + 2 * PAD) / sky.length);
  for (let i = 0; i < sky.length; i++) { g.fillStyle(sky[i], 1); g.fillRect(X0, -PAD + i * bh, FW, bh + 1); }
  // Warm horizon glow
  g.fillStyle(0xf0e0c0, .08); g.fillRect(X0, 120, FW, 80);
  // Clouds — layered ellipses for volume
  for (const [cx, cy, rw, rh] of [[100, 20, 110, 30], [370, -8, 140, 36], [650, 42, 95, 26], [210, 88, 65, 18], [530, 72, 105, 25]]) {
    g.fillStyle(0xfff, .32); g.fillEllipse(cx, cy, rw, rh);
    g.fillStyle(0xfff, .16); g.fillEllipse(cx + rw * .22, cy - rh * .18, rw * .5, rh * .4);
    g.fillStyle(0xfff, .08); g.fillEllipse(cx - rw * .18, cy + rh * .12, rw * .35, rh * .25);
  }
  G.bgGfx = g;
}

function drawStage(s) {
  const g = s.add.graphics(), X0 = -PAD, X1 = W + PAD, FW = X1 - X0;
  g.setDepth(-90);
  const drawMtn = (c, a, fn) => {
    g.fillStyle(c, a);
    g.beginPath(); g.moveTo(X0, 400);
    for (let x = X0; x <= X1; x += 6) g.lineTo(x, fn(x));
    g.lineTo(X1, 400); g.closePath(); g.fillPath();
  };
  // Far mountains (misty green — Cerros Orientales)
  drawMtn(0x3a6a4a, 1, x => 155 + Math.sin(x * .005) * 55 + Math.sin(x * .013 + 1) * 30 + Math.cos(x * .009) * 22);
  // Mountain mist band
  g.fillStyle(0x90b8d4, .1); g.fillRect(X0, 185, FW, 45);
  // Near mountains (rich dark green)
  drawMtn(0x1e4a2a, 1, x => 215 + Math.sin(x * .007 + 2) * 48 + Math.sin(x * .021) * 18);
  // Highlight ridge on near mountains
  drawMtn(0x2a6a3a, .25, x => 222 + Math.sin(x * .007 + 2) * 46 + Math.sin(x * .021) * 17);
  // Tall buildings (Bogotá skyline)
  for (let x = X0 + 15; x < X1; x += 65) {
    const bh = 80 + ((x * 7 + 31) & 127), by = 400 - bh, bw = 28 + ((x * 3) & 7);
    g.fillStyle(0x484860, 1); g.fillRect(x, by, bw, bh);
    g.fillStyle(0x3a3a50, 1); g.fillRect(x + bw - 5, by, 5, bh);
    g.fillStyle(0x5a5a70, 1); g.fillRect(x, by, bw, 3);
    for (let wy = by + 10; wy < 392; wy += 12)
      for (let wx = x + 3; wx < x + bw - 3; wx += 8) {
        g.fillStyle(((wx * 3 + wy * 7) & 7) > 2 ? 0xffe888 : 0x28283a, ((wx + wy) & 3) ? .5 : .3);
        g.fillRect(wx, wy, 4, 6);
      }
  }
  // Colorful houses (La Candelaria)
  const hc = [0xc83030, 0x2266bb, 0xd4a020, 0x2e8a48, 0xd06828, 0x9a3388, 0xc75080, 0xe8e0c8];
  for (let x = X0, ci = 0; x < X1; x += 24, ci++) {
    const h = 30 + ((x * 3 + 17) & 31), by = 400 - h;
    g.fillStyle(hc[(ci * 3 + 1) % hc.length], 1); g.fillRect(x, by, 22, h);
    g.fillStyle(0x000, .12); g.fillRect(x + 18, by, 4, h);
    g.fillStyle(0x000, .18); g.fillRect(x - 1, by, 24, 2);
    g.fillStyle(0x1a1a1a, .65); g.fillRect(x + 8, 400 - 16, 6, 16);
    g.fillStyle(0xddddcc, .5); g.fillRect(x + 3, by + 8, 5, 5); g.fillRect(x + 14, by + 8, 5, 5);
  }

  // Festive carnival string lights across the plaza skyline
  g.lineStyle(1.5, 0x111122, 0.6);
  g.beginPath();
  g.moveTo(X0, 275);
  for (let x = X0; x <= X1; x += 12) {
    const ly = 275 + Math.sin(x * 0.012) * 18;
    g.lineTo(x, ly);
  }
  g.strokePath();
  const lightColors = [0xff3355, 0xffd166, 0x33cc66, 0x3399ff, 0xff66cc, 0xffaa00];
  for (let x = X0 + 10, li = 0; x < X1; x += 24, li++) {
    const ly = 275 + Math.sin(x * 0.012) * 18;
    const lc = lightColors[li % lightColors.length];
    g.fillStyle(lc, 0.9);
    g.fillCircle(x, ly + 4, 3.5);
    g.fillStyle(0xfff, 0.8);
    g.fillCircle(x, ly + 3, 1.2);
  }

  // Dancing spectators / crowd along the plaza curb
  for (let x = X0 + 20, ci = 0; x < X1; x += 32, ci++) {
    if ((x > 110 && x < 230) || (x > 570 && x < 690)) continue; // Keep space around main fighters open
    const cy = 398;
    const shirtCol = [0xee4444, 0x3388ee, 0x44bb55, 0xf0aa20, 0x9944bb, 0xee7799][ci % 6];
    g.fillStyle(0x222233, 1);
    g.fillRect(x - 2, cy - 8, 2, 8); g.fillRect(x + 2, cy - 8, 2, 8);
    g.fillStyle(shirtCol, 1);
    g.fillRect(x - 4, cy - 18, 9, 10);
    g.fillStyle(0xdeac92, 1);
    g.fillCircle(x, cy - 22, 4);
    g.fillStyle(0x221100, 1);
    g.fillRect(x - 4, cy - 26, 8, 4);
    g.fillStyle(shirtCol, 1);
    if (ci % 2 === 0) {
      g.fillRect(x - 6, cy - 22, 3, 7); g.fillRect(x + 5, cy - 25, 3, 9);
    } else {
      g.fillRect(x - 6, cy - 25, 3, 9); g.fillRect(x + 5, cy - 22, 3, 7);
    }
  }

  G.stageGfx = g;
}

function drawFloor(s) {
  const g = s.add.graphics(), FW = W + 2 * PAD, X0 = -PAD, FH = H + PAD - 400;
  g.setDepth(-80);
  // Concrete plaza
  g.fillStyle(0x989490, 1); g.fillRect(X0, 400, FW, FH);
  // Tile joints
  g.fillStyle(0x000, .06);
  for (let y = 400; y < H + PAD; y += 48) g.fillRect(X0, y, FW, 1);
  for (let x = X0; x < W + PAD; x += 48) g.fillRect(x, 400, 1, FH);
  // Depth darkening
  g.fillStyle(0x000, .05); g.fillRect(X0, 500, FW, H + PAD - 500);
  // Surface specks
  for (let i = 0; i < 30; i++) {
    g.fillStyle(i & 1 ? 0x868280 : 0xaaa6a0, .4);
    g.fillRect(((i * 73 + 11) % W) + X0, 410 + ((i * 37) % (H - 420 + PAD)), 2, 1);
  }
  // Curb edge
  g.fillStyle(0x666660, 1); g.fillRect(X0, 400, FW, 3);
  g.fillStyle(0xb0aca6, .35); g.fillRect(X0, 400, FW, 1);
  G.floorGfx = g;
}

function drawPlayer(s, idx) {
  const p = players[idx];
  const g = s.add.graphics();
  // g.setDepth(-50);
  g.setScale(idx === 0 ? 9 : -9, 9);
  const pose = p.sprites[p.poseIdx % p.sprites.length];
  dsp(g, pose, 0, 0, true);
  G.playerLayers[idx] = g;
  p.gfx = g;
}

function drawTugBar(s) {
  const g = s.add.graphics();
  G.hudLayer.add(g);
  G.tugGfx = g;
}

function drawTugGfx() {
  const g = G.tugGfx;
  if (!g) return;
  G.barVis += (G.bar - G.barVis) * 0.12;
  g.clear();
  const bx = 200, by = 18, bw = 400, bh = 20;
  // Thick pixel border (NES style)
  g.fillStyle(0x000, 1); g.fillRect(bx - 8, by - 8, bw + 16, bh + 16);
  g.fillStyle(0x2a2a3a, 1); g.fillRect(bx - 4, by - 4, bw + 8, bh + 8);
  // Bar background
  g.fillStyle(0x0a0a14, 1); g.fillRect(bx, by, bw, bh);
  // Left half P1, right half P2
  g.fillStyle(COL.p1H, 0.3); g.fillRect(bx, by, bw / 2, bh);
  g.fillStyle(COL.p2H, 0.3); g.fillRect(bx + bw / 2, by, bw / 2, bh);
  // Center divider
  g.fillStyle(0xfff, 0.5); g.fillRect(bx + bw / 2 - 1, by - 4, 2, bh + 8);
  // Pixel marker
  const mx = Math.round(bx + ((G.barVis + BAR_MAX) / (2 * BAR_MAX)) * bw);
  const danger = Math.abs(G.barVis) > 80;
  const mc = G.barVis >= 0 ? COL.p1H : COL.p2H;
  g.fillStyle(0x000, 1); g.fillRect(mx - 8, by - 4, 16, bh + 8);
  g.fillStyle(danger && (state.t >> 4 & 1) ? 0xff3333 : mc, 1); g.fillRect(mx - 6, by - 2, 12, bh + 4);
  g.fillStyle(0xfff, 1); g.fillRect(mx - 4, by, 4, 3);
}

function drawArrowGfx(s) {
  for (let pi = 0; pi < 2; pi++) {
    for (let i = 0; i < 4; i++) {
      const g = s.add.graphics();
      drawArrow(g, LANE_X[pi][i], HIT_Y, ARROW_SCALE, DIR_ROT[i], COL.arrowL, COL.arrowD);
      players[pi].arrows.push(g);
      G.hudLayer.add(g);
    }
  }
}

function drawTitleScreen(s) {
  G.hudLayer.setVisible(0);
  G.winLayer.setVisible(0);
  G.titleLayer.removeAll(1);
  G.titleLayer.setVisible(1);

  // Black background
  const bg = s.add.rectangle(W / 2, H / 2, W, H, 0x000, 1);
  G.titleLayer.add(bg);

  // Title sprite (31x19) centered near top
  const titleGfx = s.add.graphics();
  titleGfx.setScale(10, 10);
  titleGfx.x = W / 2 - 20;
  titleGfx.y = 170;
  dsp(titleGfx, TITLE_SPRITE, 0, 0, {});
  G.titleLayer.add(titleGfx);
  G.titleSpriteGfx = titleGfx;

  // Mode selector text (will be updated by updateTitleMode)
  G.titleModeTxts = [];
  updateTitleMode(s);

  // // Bottom text
  // const startTxt = cTxt(s, W / 2, H - 50, 'PRESIONA CUALQUIER TECLA', 16, '#fff', 1);
  // G.titleLayer.add(startTxt);
  // G.startText = startTxt;

  // 4 dancing characters: 2 on the left, 2 on the right
  // Cycle through DANCERS if fewer than 4
  const dCount = DANCERS.length;
  const dancerIndices = [0 % dCount, 1 % dCount, (dCount > 2 ? 2 : 0) % dCount, (dCount > 3 ? 3 : 1) % dCount];
  G.titleDancers = [];
  const positions = [
    { x: 100, y: 420, flip: 1 },   // left back
    { x: 185, y: 440, flip: 1 },   // left front
    { x: W - 185, y: 440, flip: -1 }, // right front
    { x: W - 100, y: 420, flip: -1 }, // right back
  ];
  for (let i = 0; i < 4; i++) {
    const di = dancerIndices[i];
    const sprites = DANCERS[di][1];
    const g = s.add.graphics();
    const scale = 7;
    g.setScale(positions[i].flip * scale, scale);
    g.x = positions[i].x;
    g.y = positions[i].y;
    const poseIdx = 0;
    dsp(g, sprites[poseIdx], 0, 0, true);
    G.titleLayer.add(g);
    G.titleDancers.push({ gfx: g, sprites, poseIdx, dancerIdx: di, timer: 0 });
  }
}

function updateTitleMode(s) {
  // Remove old mode texts
  if (G.titleModeTxts) {
    for (const t of G.titleModeTxts) { if (t && t.active) t.destroy(); }
  }
  const m1Sel = G.mode === '1p';
  const m2Sel = G.mode === '2p';
  const m1Tx = cTxt(s, W / 2 - 20, H / 2 + 50, m1Sel ? '> 1 JUGADOR' : '  1 JUGADOR', 22, m1Sel ? '#fff' : '#555', 1);
  const m2Tx = cTxt(s, W / 2 - 20, H / 2 + 90, m2Sel ? '> 2 JUGADORES' : '  2 JUGADORES', 22, m2Sel ? '#fff' : '#555', 1);
  G.titleLayer.add([m1Tx, m2Tx]);
  G.titleModeTxts = [m1Tx, m2Tx];
}

function drawPatternBg(s) {
  if (G.menuBgGraphics) G.menuBgGraphics.destroy();
  const bg = s.add.graphics();
  G.menuBgGraphics = bg;

  // Left half (Yellowish)
  bg.fillStyle(0xF9E076, 1);
  bg.fillRect(0, 0, W / 2 + 50, H);
  // Right half (Dark purplish)
  bg.fillStyle(0x3B2E5A, 1);
  bg.fillRect(W / 2 + 50, 0, W / 2 - 50, H);

  for (let y = 0; y < H; y += 20) {
    for (let x = 0; x < W; x += 20) {
      if ((x + y) % 40 === 0) {
        bg.fillStyle(x < W / 2 + 50 ? 0xDFB64F : 0x1F1635, 1);
        bg.fillRect(x, y, 4, 4);
      }
    }
  }

  G.worldLayer.add(bg);
  G.worldLayer.sendToBack(bg);
}

function drawCharSelScreen(s) {
  drawPatternBg(s);
  G.hudLayer.setVisible(0);
  G.winLayer.setVisible(0);
  G.titleLayer.removeAll(1);
  G.titleLayer.setVisible(1);

  [G.bgGfx, G.stageGfx, G.floorGfx].forEach(g => g && g.setVisible(0));

  for (let i = 0; i < 2; i++) {
    const px = players[i].center.x;
    if (i === 0 && G.mode === '1p') {
      G.titleLayer.add(cTxt(s, px, 155, 'RIVAL (CPU)', 16, '#fff', 1));
      let stateTxt = G.aiPicking ? 'ROULETTE' : (G.charSel[0].ok ? 'LISTO' : 'ESPERANDO...');
      G.titleLayer.add(cTxt(s, px, 185, stateTxt, stateTxt === 'ESPERANDO...' ? 14 : 18, stateTxt === 'ESPERANDO...' ? '#666666' : '#fff', 1));
    } else {
      if (G.charSel[i].ok) G.titleLayer.add(cTxt(s, px, 185, 'LISTO', 20, '#fff', 1));
    }
    G.titleLayer.add(cTxt(s, px, 488, players[i].name, 22, '#fff', 1));
  }
}

function drawSongSelScreen(s) {
  drawPatternBg(s);
  G.hudLayer.setVisible(0);
  G.winLayer.setVisible(0);
  G.titleLayer.removeAll(1);
  G.titleLayer.setVisible(1);

  if (G.bgGfx) G.bgGfx.setVisible(0);
  if (G.stageGfx) G.stageGfx.setVisible(0);
  if (G.floorGfx) G.floorGfx.setVisible(0);

  G.songListItems = [];
  G.songListGfx = s.add.graphics();
  G.titleLayer.add(G.songListGfx);

  for (let i = 0; i < SONGS.length; i++) {
    const name = cTxt(s, 0, 0, SONGS[i].name, 24, '#fff', 1);
    const meta = cTxt(s, 0, 0, SONGS[i].genre + '  •  ' + SONGS[i].bpm, 12, '#cccccc', 0);
    G.titleLayer.add([name, meta]);
    G.songListItems.push({ name, meta });
  }

  // Difficulty Pill
  const diffTxts = ['FÁCIL', 'MEDIO', 'DIFÍCIL'];
  const diffTx = cTxt(s, 625, 40, '< DIFICULTAD: ' + diffTxts[G.difficulty] + ' >', 20, '#fff', 1);
  G.titleLayer.add([diffTx]);
  G.diffTx = diffTx;

  playSongPreview(s, G.selSong);
}

function showWinScreen(winner) {
  G.hudLayer.setVisible(0);
  G.titleLayer.setVisible(0);
  G.winLayer.removeAll(1);
  G.winLayer.setVisible(1);

  const s = G.titleLayer.scene;
  const bg = s.add.rectangle(W / 2, H / 2, W, H, 0x000, 0.65);
  const col = winner === 0 ? '#ff5577' : '#77dd55';
  const t1 = cTxt(s, W / 2, H / 2 - 90, '¡K.O.!', 68, '#fff200', 1).setStroke('#000000', 6);
  const t2 = cTxt(s, W / 2, H / 2 - 20, `${players[winner].name} GANA LA RUMBA`, 28, col, 1).setStroke('#000000', 4);
  const w = players[winner];
  const t3 = cTxt(s, W / 2, H / 2 + 35, `PERFECT: ${w.perfect}   GOOD: ${w.good}   MISS: ${w.miss}`, 16, '#fff', 1).setStroke('#000000', 3);
  const t4 = cTxt(s, W / 2, H / 2 + 90, 'PRESIONA START PARA VOLVER', 20, '#ffd166', 1).setStroke('#000000', 4);

  G.winLayer.add([bg, t1, t2, t3, t4]);
  G.winText = t4;
}

/* === STATE TRANSITIONS === */
function startBattle() {
  if (G.music) { G.music.stop(); G.music = null; }
  if (G.menuMusic) { G.menuMusic.stop(); G.menuMusic = null; }
  if (G.previewMusic) { G.previewMusic.stop(); G.previewMusic = null; }
  state.v = STATE.BATTLE;
  
  if (G.bgGfx) G.bgGfx.setVisible(1);
  if (G.stageGfx) G.stageGfx.setVisible(1);
  if (G.floorGfx) G.floorGfx.setVisible(1);
  if (G.menuBgGraphics) G.menuBgGraphics.setVisible(0);
  
  state.t = 0;
  state.winner = -1;
  state.songStart = 0;
  state.songEnd = 0;
  G.audioStart = 0; G.songLen = 0;
  G.bar = 0; G.barVis = 0;
  G.lastTurn = -1;
  for (const p of players) {
    p.combo = 0; p.score = 0;
    p.perfect = 0; p.good = 0; p.miss = 0;
    p.arrowBounce = [0, 0, 0, 0];
    if (p.notes) {
      for (const n of p.notes) { if (n.gfx) { n.gfx.destroy(); n.gfx = null; } }
    }
    p.notes = []; p.seq = 0;
    if (p.comboTxt) p.comboTxt.setText('');
  }
  G.notesSpawned = 0;
  if (G.notesSong) buildSchedule();
  G.titleLayer.setVisible(0);
  G.winLayer.setVisible(0);
  G.hudLayer.setVisible(1);
  clearInputs();
  if (G.notesSong) startMusic();
}

function startMusic() {
  if (!G.notesSong) return;
  const ctx = G.titleLayer.scene.sound.context;
  G.audioStart = ctx.currentTime + 0.08; // playMidi internal base offset
  G.music = playMidi(ctx, G.midiText, len => {
    if (state.v === STATE.BATTLE) G.songLen = len;
  });
}

function endBattle() {
  if (G.music) { G.music.stop(); G.music = null; }
  let w;
  if (G.bar >= BAR_MAX) w = 0;
  else if (G.bar <= -BAR_MAX) w = 1;
  else w = G.bar > 0 ? 0 : 1;
  state.v = STATE.WIN;
  state.winner = w;
  for (const p of players) {
    if (p.notes) {
      for (const n of p.notes) { if (n.gfx) { n.gfx.destroy(); n.gfx = null; } }
    }
    p.notes = [];
  }
  G.hudLayer.setVisible(0);
  clearInputs();
  showWinScreen(w);
}

function buildSchedule() {
  G.notes = [];
  const song = G.notesSong;
  const tempos = song.events.filter(e => e.kind === 'T');
  const div = song.division;
  const diff = G.difficulty; // 0=EASY 1=MEDIUM 2=HARD

  // Min seconds between arrows per difficulty (configured in DIFFICULTY_GAPS at top)
  const gaps = DIFFICULTY_GAPS;

  // Gather every melodic/harmonic attack from every instrument
  const cand = [];
  for (const e of song.events) {
    if (e.kind !== 'N' || e.channel === 9) continue;
    const t = secondsAt(e.tick, tempos, div);
    if (t < LEAD_IN) continue;
    cand.push({ t, tick: e.tick, pitch: e.pitch });
  }
  cand.sort((a, b) => a.t - b.t);

  // Group simultaneous attacks (~same instant). Within a group the HIGHEST
  // pitch is the primary note; a lone low note is primary too. Everything
  // else is secondary accompaniment.
  const groups = [];
  for (const c of cand) {
    const g = groups.at(-1);
    if (g && c.t - g.t < 0.05) g.push(c);
    else groups.push([c]);
  }

  const kept = [];
  let lastT = -9;
  for (const g of groups) {
    g.sort((a, b) => b.pitch - a.pitch);
    const seen = {};
    let rank = 0;
    for (const n of g) {
      if (seen[n.pitch]) continue; // same pitch doubled across instruments
      seen[n.pitch] = 1;
      const primary = rank === 0;
      rank++;
      if (diff === 0 && !primary) continue;
      if (diff === 1 && !primary && n.tick % (div / 2) !== 0) continue;
      if (n.t - lastT < gaps[diff]) continue;
      lastT = n.t;
      kept.push(n);
    }
  }

  // Lane from pitch quartiles spread across the 4 directions
  const ps = kept.map(k => k.pitch).sort((a, b) => a - b);
  const q = i => ps[Math.floor((ps.length - 1) * i / 4)] ?? 60;
  for (const k of kept) {
    let dir;
    if (k.pitch < q(1)) dir = DIR.L;
    else if (k.pitch < q(2)) dir = DIR.D;
    else if (k.pitch < q(3)) dir = DIR.U;
    else dir = DIR.R;
    G.notes.push({ time: k.t, dir, turn: 1 - (Math.floor(k.t / SEC_LEN) % 2) });
  }
  G.notesTotal = G.notes.length;
}

/* === UPDATE LOOP === */
function update(time, delta) {
  if (G.blurred) {
    clearInputs();
    return;
  }
  if (delta > 500) delta = 0;
  state.t += delta;

  const s = G.titleLayer.scene;
  
  if (state.v === STATE.SPLASH) {
    if (state.t > 2000 && !G.splashFading) {
      G.splashFading = 1;
      drawTitleScreen(s); // Draw title screen so it's under the splash screen during fade out
      s.tweens.add({
        targets: G.splashLayer,
        alpha: 0,
        duration: 1000,
        onComplete: () => {
          state.v = STATE.TITLE;
          state.t = 0;
          G.splashLayer.setVisible(0);
        }
      });
    }
    // Also animate dancers during the fade out
    if (G.splashFading && G.titleDancers) {
      const DANCE_INTERVAL = 400;
      for (const d of G.titleDancers) {
        d.timer += delta;
        if (d.timer >= DANCE_INTERVAL) {
          d.timer -= DANCE_INTERVAL;
          d.poseIdx = (d.poseIdx + 1) % d.sprites.length;
          d.gfx.clear();
          dsp(d.gfx, d.sprites[d.poseIdx], 0, 0, true);
        }
      }
    }
  } else if (state.v === STATE.TITLE) {
    if (justPressed.P1_U || justPressed.P1_D || justPressed.P2_U || justPressed.P2_D) {
      playMenuBlip();
      G.mode = G.mode === '1p' ? '2p' : '1p';
      updateTitleMode(s);
    }
    if (justPressed.START1 || justPressed.START2 || justPressed.P1_1 || justPressed.P2_1) {
      playMenuSelect();
      state.v = STATE.CHARSEL;
      G.charSel[0] = { cursor: 0, ok: 0 };
      G.charSel[1] = { cursor: 1 % DANCERS.length, ok: 0 };
      G.aiPicking = 0;
      G.waitSong = 0;
      updateStagePlayer(0, G.charSel[0].cursor, 1);
      updateStagePlayer(1, G.charSel[1].cursor, 1);
      drawCharSelScreen(s);
    }
    // Animate dancing characters on title screen
    if (G.titleDancers) {
      const DANCE_INTERVAL = 400; // ms between pose changes
      for (const d of G.titleDancers) {
        d.timer += delta;
        if (d.timer >= DANCE_INTERVAL) {
          d.timer -= DANCE_INTERVAL;
          d.poseIdx = (d.poseIdx + 1) % d.sprites.length;
          d.gfx.clear();
          dsp(d.gfx, d.sprites[d.poseIdx], 0, 0, true);
        }
      }
    }
    if (G.startText && G.startText.active) {
      G.startText.setAlpha(0.5 + 0.5 * Math.sin(state.t * 0.003));
    }
  } else if (state.v === STATE.CHARSEL) {
    if (G.mode === '1p') {
      if (!G.charSel[1].ok) {
        if (justPressed.P1_U || justPressed.P1_D || justPressed.P2_U || justPressed.P2_D) {
          playMenuBlip();
          updateStagePlayer(1, (G.charSel[1].cursor + 1) % DANCERS.length);
        }
        if (justPressed.P1_1 || justPressed.P2_1 || justPressed.START1 || justPressed.START2) {
          playMenuSelect();
          G.charSel[1].ok = 1;
          G.aiPicking = 1;
          G.aiTick = 0;
          G.aiTicksLeft = 12;
          G.charSel[0].ok = 0;
          drawCharSelScreen(s);
        }
      }
      if (G.aiPicking) {
        G.aiTick += delta;
        if (G.aiTick > 80) {
          G.aiTick -= 80;
          G.aiTicksLeft--;
          updateStagePlayer(0, (G.charSel[0].cursor + 1) % DANCERS.length, 1);
          playMenuBlip();
          if (G.aiTicksLeft <= 0) {
            if (DANCERS.length > 1 && G.charSel[0].cursor === G.charSel[1].cursor) {
              updateStagePlayer(0, (G.charSel[0].cursor + 1) % DANCERS.length, 1);
            }
            G.aiPicking = 0;
            G.charSel[0].ok = 1;
            playMenuSelect();
          }
          drawCharSelScreen(s);
        }
      }
    } else {
      for (let p = 0; p < 2; p++) {
        if (!G.charSel[p].ok) {
          if (justPressed[`P${p+1}_U`] || justPressed[`P${p+1}_D`]) {
            playMenuBlip();
            updateStagePlayer(p, (G.charSel[p].cursor + 1) % DANCERS.length);
          }
          if (justPressed[`P${p+1}_1`] || justPressed[`START${p+1}`]) {
            playMenuSelect();
            G.charSel[p].ok = 1;
            drawCharSelScreen(s);
          }
        }
      }
    }
    if (G.charSel[0].ok && G.charSel[1].ok && !G.waitSong) {
      G.waitSong = 1;
      setTimeout(() => {
        state.v = STATE.SONGSEL;
        G.waitSong = 0;
        drawSongSelScreen(s);
      }, 750);
    }
  } else if (state.v === STATE.SONGSEL) {
    if (justPressed.P1_U || justPressed.P2_U) {
      playMenuBlip();
      G.selSong = (G.selSong - 1 + SONGS.length) % SONGS.length;
      playSongPreview(s, G.selSong);
    }
    if (justPressed.P1_D || justPressed.P2_D) {
      playMenuBlip();
      G.selSong = (G.selSong + 1) % SONGS.length;
      playSongPreview(s, G.selSong);
    }
    if (justPressed.P1_L || justPressed.P2_L) {
      if (G.difficulty > 0) {
        playMenuBlip();
        G.difficulty--;
        const diffTxts = ['FÁCIL', 'MEDIO', 'DIFÍCIL'];
        if (G.diffTx) G.diffTx.setText('< DIFICULTAD: ' + diffTxts[G.difficulty] + ' >');
      }
    }
    if (justPressed.P1_R || justPressed.P2_R) {
      if (G.difficulty < 2) {
        playMenuBlip();
        G.difficulty++;
        const diffTxts = ['FÁCIL', 'MEDIO', 'DIFÍCIL'];
        if (G.diffTx) G.diffTx.setText('< DIFICULTAD: ' + diffTxts[G.difficulty] + ' >');
      }
    }
    if (justPressed.START1 || justPressed.START2 || justPressed.P1_1 || justPressed.P2_1) {
      if (!G.pendingStart && SONGS.length > 0) {
        playCoinStart();
        G.pendingStart = 1;
        unpack(SONGS[G.selSong].data).then(song => {
          G.midiText = song;
          G.notesSong = decode(song);
          G.pendingStart = 0;
          startBattle();
        });
      }
    }
    G.selSongVis = G.selSongVis ?? G.selSong;
    G.selSongVis += (G.selSong - G.selSongVis) * 0.2;
    if (G.songListGfx && G.songListItems) {
      const g = G.songListGfx; g.clear();
      for (let i = 0; i < SONGS.length; i++) {
        const d = i - G.selSongVis, m = Math.abs(d);
        const sy = H/2 + d * 80, sx = 650 - m ** 1.5 * 20;
        const a = Math.max(0, 1 - m);
        
        g.fillStyle(0x1A102A, 0.7 + a * 0.3);
        if (a > 0.01) g.lineStyle(3, 0xfff, a);
        g.fillRoundedRect(sx - 150 - a*10, sy - 27 - a*5, 300 + a*20, 55 + a*10, 12);
        if (a > 0.01) g.strokeRoundedRect(sx - 150 - a*10, sy - 27 - a*5, 300 + a*20, 55 + a*10, 12);

        const t = G.songListItems[i];
        t.name.setPosition(sx, sy - 8 - a*4).setFontSize(18 + a*6).setColor(a > .5 ? '#fff' : '#aaa').setAngle(i === G.selSong ? Math.sin(state.t * .01) * 2.5 * a : 0);
        t.meta.setPosition(sx, sy + 14 + a*2).setColor(a > .5 ? '#ccc' : '#777');
      }
    }
  } else if (state.v === STATE.BATTLE) {
    updateBattle(delta);
  } else if (state.v === STATE.WIN) {
    if (G.winText && G.winText.active) {
      G.winText.setScale(1 + Math.sin(state.t * 0.005) * 0.08);
    }
    if (justPressed.START1 || justPressed.START2 || justPressed.P1_1 || justPressed.P2_1) {
      state.v = STATE.TITLE;
      drawTitleScreen(s);
      startMenuMusic();
    }
  }

  drawDynamicElements();
  animateCharacters(delta);
  updateCamera();

  for (const k in justPressed) justPressed[k] = 0;
  for (const k in justReleased) justReleased[k] = 0;
}

function drawDynamicElements() {
  drawTugGfx();
}

function animateCharacters(delta) {
  const bob = state.v === STATE.TITLE ? 0 : Math.sin(state.t * 0.005) * 2;
  for (let i = 0; i < 2; i++) {
    const p = players[i];
    const g = G.playerLayers[i];
    if (!g) continue;

    // Decay pulse offset back to center (fast snap-back)
    if (p.pulseT > 0) {
      p.pulseT = Math.max(0, p.pulseT - delta * 0.008);
      const ease = p.pulseT * p.pulseT; // quadratic ease-out
      p.pulseDx *= ease > 0 ? Math.pow(0.92, delta / 16) : 0;
      p.pulseDy *= ease > 0 ? Math.pow(0.92, delta / 16) : 0;
    } else {
      p.pulseDx = 0;
      p.pulseDy = 0;
    }

    if (p.isSlidingOut) {
      p.slideOffset = Math.min(p.slideTarget, (p.slideOffset || 0) + delta * 2.5);
      if (p.slideOffset >= p.slideTarget) {
        p.isSlidingOut = 0;
        p.name = p.nextName;
        p.sprites = p.nextSprites;
        p.poseIdx = 0;
        p.danceTimer = 1000; // Force immediate dance
        if (g) { g.clear(); dsp(g, p.sprites[0], 0, 0, true); }
        if (state.v === STATE.CHARSEL) drawCharSelScreen(G.titleLayer.scene);
      }
    } else {
      if (p.slideOffset > 0) p.slideOffset = Math.max(0, p.slideOffset - delta * 2.5);
    }

    // Dance in CHARSEL or SONGSEL
    if ((state.v === STATE.CHARSEL || state.v === STATE.SONGSEL) && !p.isSlidingOut && p.sprites.length > 0) {
      p.danceTimer = (p.danceTimer || 0) + delta;
      const danceInterval = state.v === STATE.SONGSEL ? 400 : 600;
      if (p.danceTimer >= danceInterval) {
        p.danceTimer -= danceInterval;
        p.poseIdx = (p.poseIdx + 1) % p.sprites.length;
        if (g) { g.clear(); dsp(g, p.sprites[p.poseIdx], 0, 0, true); }
      }
    }

    let cx = p.center.x;
    let cy = p.center.y;
    if (state.v === STATE.SONGSEL) {
      cx = i === 0 ? 160 : 320; // both on the left
      cy = 400;
    }

    g.x = cx + p.pulseDx;
    g.y = cy + bob - 40 + p.pulseDy + (p.slideOffset || 0);
  }
}

/* Trigger a dance pose change for the player on a successful note hit */
function triggerDancePose(pi, dir) {
  const p = players[pi];
  const numPoses = p.sprites.length;
  if (numPoses <= 0) return;

  // Map direction to pose index, cycling if fewer poses than 4 arrows
  const newPose = dir % numPoses;
  p.poseIdx = newPose;

  // Redraw the sprite with the new pose
  const g = G.playerLayers[pi];
  if (g) {
    g.clear();
    const pose = p.sprites[p.poseIdx];
    dsp(g, pose, 0, 0, true);
  }

  // Start pulsation: random direction snap
  const angle = Math.random() * Math.PI * 2;
  const strength = 8 + Math.random() * 6; // 8-14px snap
  p.pulseDx = Math.cos(angle) * strength;
  p.pulseDy = Math.sin(angle) * strength;
  p.pulseT = 1.0;
}

function getSongTime() {
  const ctx = G.titleLayer?.scene?.sound?.context;
  if (!ctx || !G.audioStart) return 0;
  return ctx.currentTime - G.audioStart;
}

function updateCamera() {
  if (!G.cam) return;
  let tx = W / 2, ty = 300, tz = 1;
  if (state.v === STATE.BATTLE) {
    const songT = getSongTime();
    const hasNotes = players[0].notes.length > 0 || players[1].notes.length > 0;
    if (hasNotes) {
      const turn = 1 - (Math.floor((songT + TRAVEL_TIME) / SEC_LEN) % 2);
      tx = turn === 0 ? 300 : 500;
      ty = 285;
      tz = 1.15;
    } else {
      tx = W / 2;
      ty = 300;
      tz = 1;
    }
  } else if (state.v === STATE.CHARSEL) {
    tx = W / 2;
    ty = 330;
    tz = 1.05;
  } else if (state.v === STATE.WIN) {
    tx = state.winner === 0 ? 250 : 550;
    ty = 320;
    tz = 1.18;
  }
  G.camX += (tx - G.camX) * .07;
  G.camY += (ty - G.camY) * .07;
  G.camZ += (tz - G.camZ) * .06;
  G.cam.setZoom(G.camZ);
  G.cam.centerOn(G.camX, G.camY);
}

function updateBattle(delta) {
  const songT = getSongTime();
  const turn = 1 - (Math.floor(songT / SEC_LEN) % 2);
  G.lastTurn = turn;

  while (G.notesSpawned < G.notes.length && G.notes[G.notesSpawned].time - TRAVEL_TIME <= songT) {
    const n = G.notes[G.notesSpawned];
    players[n.turn].notes.push({ targetTime: n.time, dir: n.dir, hit: 0, dead: 0, gfx: null, y: 0 });
    G.notesSpawned++;
  }

  // 1P Mode CPU hit automation for Player 0
  if (G.mode === '1p') {
    for (const n of players[0].notes) {
      if (!n.dead && !n.hit && Math.abs(n.y - HIT_Y) < 14) {
        const acc = G.difficulty === 0 ? 0.85 : (G.difficulty === 1 ? 0.93 : 0.99);
        if (Math.random() < acc) tryHit(0, n.dir, songT);
      }
    }
  }

  for (let pi = 0; pi < 2; pi++) {
    const p = players[pi];
    const xs = LANE_X[pi];
    const alive = [];
    for (const n of p.notes) {
      if (n.dead) { if (n.gfx) { n.gfx.destroy(); n.gfx = null; } continue; }
      const y = HIT_Y - (n.targetTime - songT) * (HIT_Y / TRAVEL_TIME);
      n.y = y;
      if (y > HIT_Y + HIT_WIN + 20) {
        n.dead = 1; n.hit = 1;
        onMiss(pi, n.dir);
        if (n.gfx) { n.gfx.destroy(); n.gfx = null; }
        continue;
      }
      if (!n.gfx) {
        n.gfx = G.fxLayer.scene.add.graphics();
        G.hudLayer.add(n.gfx);
      }
      n.gfx.clear();
      drawArrow(n.gfx, xs[n.dir], y, ARROW_SCALE, DIR_ROT[n.dir], ARROW_LIGHT[n.dir], ARROW_DARK[n.dir]);
      alive.push(n);
    }
    p.notes = alive;

    for (let d = 0; d < 4; d++) {
      if (p.arrowBounce && p.arrowBounce[d] > 0) {
        p.arrowBounce[d] = Math.max(0, p.arrowBounce[d] - delta * BOUNCE_DECAY);
      }
      const b = p.arrowBounce ? p.arrowBounce[d] : 0;
      const curScale = ARROW_SCALE * (1 + BOUNCE_SCALE * b);
      const curY = HIT_Y - BOUNCE_Y * b;
      const keys = p.dirKeys ? p.dirKeys[d] : [p.keys[d]];
      const isHuman = G.mode !== '1p' || pi === 1;
      const isHeld = isHuman && (keys.some(k => held[k]) || (G.mode === '1p' && pi === 1 && players[0].dirKeys[d].some(k => held[k])));
      const isPressed = isHuman && (keys.some(k => justPressed[k]) || (G.mode === '1p' && pi === 1 && players[0].dirKeys[d].some(k => justPressed[k])));
      const g = p.arrows[d];
      if (g) {
        g.clear();
        drawArrow(g, xs[d], curY, curScale, DIR_ROT[d],
          isHeld ? ARROW_LIGHT[d] : COL.arrowL,
          isHeld ? ARROW_DARK[d] : COL.arrowD);
      }
      if (G.mode !== '1p' || pi === 1) {
        if (isPressed) tryHit(pi, d, songT);
      }
    }
  }

  if (G.bar >= BAR_MAX || G.bar <= -BAR_MAX) endBattle();
  else if (G.songLen && songT >= G.songLen) endBattle();
}

function showJudgment(scene, pi, dir, rating) {
  if (!scene || !G.hudLayer) return;
  const x = LANE_X[pi][dir ?? 1], y = HIT_Y - 32;
  const col = rating === 'PERFECTO' ? '#ffd166' : (rating === 'BIEN' ? '#77dd55' : '#ff5577');
  const txt = scene.add.text(x, y, rating, { fontFamily: 'monospace', fontSize: '15px', color: col, fontStyle: 'bold' }).setOrigin(0.5);
  txt.setStroke('#000000', 4);
  txt.setDepth(150);
  G.hudLayer.add(txt);

  scene.tweens.add({
    targets: txt,
    y: y - 28,
    alpha: 0,
    scale: rating === 'PERFECTO' ? 1.25 : 1.05,
    duration: 380,
    ease: 'Power2',
    onComplete: () => txt.destroy()
  });

  if (rating === 'PERFECTO') {
    for (let i = 0; i < 6; i++) {
      const p = scene.add.rectangle(x, y, 4, 4, [0xffd166, 0xff5577, 0x77dd55, 0x29aefd][i % 4]);
      p.setDepth(150);
      G.hudLayer.add(p);
      const angle = (i / 6) * Math.PI * 2;
      const speed = 25 + Math.random() * 20;
      scene.tweens.add({
        targets: p,
        x: x + Math.cos(angle) * speed,
        y: y + Math.sin(angle) * speed,
        alpha: 0,
        scale: 0.2,
        duration: 300,
        ease: 'Quad.easeOut',
        onComplete: () => p.destroy()
      });
    }
  }
}

function tryHit(pi, dir, songT) {
  const p = players[pi];
  let best = null, bestDist = Infinity;
  for (const n of p.notes) {
    if (n.dead || n.hit || n.dir !== dir) continue;
    const dist = Math.abs(n.y - HIT_Y);
    if (dist < bestDist && dist < HIT_WIN) { bestDist = dist; best = n; }
  }
  if (best) {
    best.hit = 1;
    best.dead = 1;
    if (best.gfx) { best.gfx.destroy(); best.gfx = null; }
    if (p.arrowBounce) p.arrowBounce[dir] = 1.0;
    let dmg;
    if (bestDist < PERFECT_WIN) {
      dmg = DMG_PERFECT; p.perfect++; p.score += 100;
      showJudgment(G.titleLayer.scene, pi, dir, 'PERFECTO');
    } else {
      dmg = DMG_GOOD; p.good++; p.score += 50;
      showJudgment(G.titleLayer.scene, pi, dir, 'BIEN');
    }
    p.combo++;
    if (p.comboTxt) p.comboTxt.setText(p.combo > 1 ? p.combo + ' COMBO' : '');
    G.bar = clamp(G.bar + (pi === 0 ? dmg : -dmg), -BAR_MAX, BAR_MAX);
    triggerDancePose(pi, dir);
  } else {
    onMiss(pi, dir);
    triggerDancePose(pi, dir);
  }
}

function onMiss(pi, dir) {
  const p = players[pi];
  p.miss++;
  p.combo = 0;
  if (p.comboTxt) p.comboTxt.setText('');
  G.bar = clamp(G.bar + (pi === 0 ? -MISS_PEN : MISS_PEN), -BAR_MAX, BAR_MAX);
  showJudgment(G.titleLayer.scene, pi, dir ?? 1, 'FALLO');
  playHurt();
}

// Damage sound: gritty descending buzz, like a fighter taking a hit
function playHurt() {
  const ctx = G.titleLayer?.scene?.sound?.context;
  if (!ctx) return;
  const t0 = ctx.currentTime;
  const g = ctx.createGain(), f = ctx.createBiquadFilter();
  f.type = 'lowpass';
  f.frequency.setValueAtTime(1200, t0);
  f.frequency.exponentialRampToValueAtTime(200, t0 + .18);
  g.gain.setValueAtTime(.22, t0);
  g.gain.exponentialRampToValueAtTime(.001, t0 + .2);
  f.connect(g);
  g.connect(ctx.destination);
  const o1 = ctx.createOscillator(), o2 = ctx.createOscillator();
  o1.type = 'sawtooth';
  o2.type = 'square';
  o1.frequency.setValueAtTime(220, t0);
  o1.frequency.exponentialRampToValueAtTime(70, t0 + .18);
  o2.frequency.setValueAtTime(110, t0);
  o2.frequency.exponentialRampToValueAtTime(45, t0 + .18);
  o2.detune.value = 15;
  o1.connect(f); o2.connect(f);
  o1.start(t0); o1.stop(t0 + .2);
  o2.start(t0); o2.stop(t0 + .2);
}

function playSynth(f1, f2, dur, g2, g3) {
  const ctx = G.titleLayer?.scene?.sound?.context;
  if (!ctx) return;
  const play = () => {
    const t0 = ctx.currentTime;
    const o = ctx.createOscillator(), g = ctx.createGain();
    o.type = 'square';
    o.frequency.setValueAtTime(f1, t0);
    o.frequency.exponentialRampToValueAtTime(f2, t0 + dur[0]);
    if (dur[2]) o.frequency.setValueAtTime(dur[2], t0 + dur[0]);

    g.gain.setValueAtTime(g2[0], t0);
    g.gain.linearRampToValueAtTime(g2[1], t0 + g3[0]);
    if (g3.length > 1) {
      g.gain.setValueAtTime(g3[1], t0 + g3[2]);
      g.gain.exponentialRampToValueAtTime(g3[3], t0 + dur[1]);
    }

    o.connect(g);
    g.connect(ctx.destination);
    o.start(t0); o.stop(t0 + dur[1]);
  };
  if (ctx.state === 'suspended') ctx.resume().then(play).catch(() => {});
  else play();
}

// Menu navigation blip sound
function playMenuBlip() {
  playSynth(440, 880, [.05, .1], [.08, .001], [.1]);
}

// Menu confirmation sound (distinct from navigation)
function playMenuSelect() {
  playSynth(660, 1320, [.08, .15], [.1, .001], [.15]);
}

// Arcade coin / match start sound
function playCoinStart() {
  playSynth(987.77, 987.77, [.08, .5, 1318.51], [.0, .1], [.02, .1, .08, .001]);
}

/* === MIDI PLAYBACK (kept from prior) === */
function playSongPreview(s, songIdx) {
  if (G.previewMusic) { G.previewMusic.stop(); G.previewMusic = null; }
  if (G.menuMusic) { G.menuMusic.stop(); G.menuMusic = null; }
  G.previewNonce = (G.previewNonce || 0) + 1;
  const nonce = G.previewNonce;
  unpack(SONGS[songIdx].data).then(data => {
    if (state.v === STATE.SONGSEL && G.selSong === songIdx && !G.pendingStart && G.previewNonce === nonce) {
      const ctx = s.sound.context;
      G.previewMusic = playMidi(ctx, data);
    }
  });
}

async function unpack(data) {
  const binary = atob(data.replace(/-/g, '+').replace(/_/g, '/'));
  const bytes = Uint8Array.from(binary, c => c.charCodeAt(0));
  const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream('deflate'));
  return new Response(stream).text();
}

function variable(data, state) {
  let value = 0, digit;
  do {
    digit = A.indexOf(data[state.pos++]);
    if (digit < 0) throw Error('invalid MIDI varint');
    if (digit !== Z) value = value * Z + digit;
  } while (digit !== Z);
  return value;
}

function fixed(data, state, width) {
  let value = 0;
  for (let i = 0; i < width; i++) {
    const digit = A.indexOf(data[state.pos++]);
    if (digit < 0) throw Error('invalid MIDI field');
    value = value * B + digit;
  }
  return value;
}

function decode(data) {
  const parts = data.split('|');
  if (parts.length !== 4 || parts[0] !== 'M5') throw Error('invalid MIDI header');
  const division = fixed(parts[1], { pos: 0 }, 2), dictionary = [];
  const ds = { pos: 0 }, count = A.indexOf(parts[2][ds.pos++]);
  for (let i = 0; i < count; i++) dictionary.push(variable(parts[2], ds));
  const body = parts[3], st = { pos: 0 }, events = [];
  let tick = 0;
  while (st.pos < body.length) {
    const kind = body[st.pos++];
    tick += variable(body, st);
    if (kind === 'T') events.push({ kind, tick, tempo: fixed(body, st, 3) * 10 });
    else if (kind === 'N' || kind === 'n') {
      const channel = A.indexOf(body[st.pos++]), pitch = fixed(body, st, 2), level = A.indexOf(body[st.pos++]);
      events.push({ kind: 'N', tick, channel, pitch, level, duration: kind === 'n' ? dictionary[A.indexOf(body[st.pos++])] : variable(body, st) });
    } else if (kind === 'G') {
      const channel = A.indexOf(body[st.pos++]), count = variable(body, st), flags = A.indexOf(body[st.pos++]);
      const pitches = [];
      for (let i = 0; i < count; i++) {
        if (!i) pitches.push(fixed(body, st, 2));
        else {
          const delta = A.indexOf(body[st.pos++]);
          pitches.push(delta === Z ? fixed(body, st, 2) - 128 : pitches[i - 1] + delta - 45);
        }
      }
      const levels = flags & 1 ? Array(count).fill(A.indexOf(body[st.pos++])) : pitches.map(() => A.indexOf(body[st.pos++]));
      const durations = flags & 2 ? Array(count).fill(flags & 4 ? dictionary[A.indexOf(body[st.pos++])] : variable(body, st)) : pitches.map(() => variable(body, st));
      for (let i = 0; i < count; i++) events.push({ kind: 'N', tick, channel, pitch: pitches[i], level: levels[i], duration: durations[i] });
    } else if (kind === 'E') return { division, events, endTick: tick };
    else throw Error('invalid MIDI event');
  }
  throw Error('missing MIDI end');
}

function secondsAt(tick, tempos, division) {
  let tempo = 500000, from = 0, seconds = 0;
  for (const t of tempos) {
    if (t.tick > tick) break;
    seconds += (t.tick - from) * tempo / division / 1e6;
    from = t.tick;
    tempo = t.tempo;
  }
  return seconds + (tick - from) * tempo / division / 1e6;
}

function noise(ctx) {
  const buffer = ctx.createBuffer(1, ctx.sampleRate, ctx.sampleRate), data = buffer.getChannelData(0);
  for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
  return buffer;
}

function oscillator(ctx, type, frequency, output, time, stop, detune = 0) {
  const source = ctx.createOscillator();
  source.type = type;
  source.frequency.setValueAtTime(frequency, time);
  source.detune.setValueAtTime(detune, time);
  source.connect(output);
  source.start(time);
  source.stop(stop);
  return source;
}

function profile(program) {
  if (program === 12 || program === 115) return { type: 'mallet', cut: 5500, attack: .003, release: .16 };
  if (program >= 32 && program < 40) return { type: 'bass', cut: 900, attack: .008, release: .1 };
  if (program >= 56 && program < 72) return { type: 'brass', cut: 2100, attack: .035, release: .11 };
  if (program >= 16 && program < 32) return { type: 'pluck', cut: 2600, attack: .006, release: .13 };
  if (program >= 8 && program < 16) return { type: 'mallet', cut: 5000, attack: .003, release: .14 };
  if (program >= 24 && program < 32) return { type: 'pluck', cut: 1800, attack: .008, release: .15 };
  if (program >= 40 && program < 56) return { type: 'string', cut: 1800, attack: .045, release: .18 };
  if (program >= 80 && program < 96) return { type: 'pad', cut: 1400, attack: .08, release: .3 };
  return { type: 'piano', cut: 3200, attack: .004, release: .2 };
}

function drum(ctx, buffer, note, filter, time, length) {
  const finish = time + Math.min(.2, Math.max(.04, length));
  if (note < 42) {
    const source = oscillator(ctx, 'sine', 140, filter, time, finish);
    source.frequency.exponentialRampToValueAtTime(46, time + .11);
    return;
  }
  const source = ctx.createBufferSource(), drumFilter = ctx.createBiquadFilter();
  source.buffer = buffer;
  drumFilter.type = note < 46 ? 'bandpass' : 'highpass';
  drumFilter.frequency.value = note < 46 ? 1800 : 6500;
  drumFilter.Q.value = 1.2;
  source.connect(drumFilter);
  drumFilter.connect(filter);
  source.start(time);
  source.stop(finish);
}

function playNote(ctx, buffer, master, channel, note, time, length) {
  const style = profile(channel.program), finish = time + length + style.release + .03;
  const level = Math.min(.14, note.level / 15 * channel.volume / 127 * channel.expression / 127 * .16);
  const amp = ctx.createGain(), filter = ctx.createBiquadFilter(), panner = ctx.createStereoPanning ? null : null;
  amp.gain.setValueAtTime(.0001, time);
  amp.gain.linearRampToValueAtTime(Math.max(.0001, level), time + style.attack);
  amp.gain.setValueAtTime(Math.max(.0001, level * .7), time + Math.max(style.attack, length * .65));
  amp.gain.exponentialRampToValueAtTime(.0001, time + length + style.release);
  filter.type = 'lowpass';
  filter.frequency.setValueAtTime(style.cut, time);
  filter.Q.value = style.type === 'brass' ? 2 : .7;
  filter.connect(amp);
  if (panner) {
    panner.pan.setValueAtTime((channel.pan - 64) / 64, time);
    amp.connect(panner); panner.connect(master);
  } else amp.connect(master);
  if (note.channel === 9) return drum(ctx, buffer, note.pitch, filter, time, length);
  const frequency = 440 * Math.pow(2, (note.pitch - 69 + (channel.bend - 8192) / 4096) / 12);
  if (style.type === 'bass') {
    oscillator(ctx, 'sawtooth', frequency, filter, time, finish);
    oscillator(ctx, 'triangle', frequency / 2, filter, time, finish, -5);
  } else if (style.type === 'brass') {
    oscillator(ctx, 'sawtooth', frequency, filter, time, finish, -6);
    oscillator(ctx, 'square', frequency, filter, time, finish, 6);
  } else if (style.type === 'mallet') {
    oscillator(ctx, 'sine', frequency, filter, time, finish);
    oscillator(ctx, 'triangle', frequency * 2, filter, time, finish);
  } else if (style.type === 'pluck' || style.type === 'piano') {
    oscillator(ctx, 'triangle', frequency, filter, time, finish, -3);
    oscillator(ctx, 'sine', frequency * 2, filter, time, finish, 3);
  } else if (style.type === 'string' || style.type === 'pad') {
    oscillator(ctx, 'sawtooth', frequency, filter, time, finish, -8);
    oscillator(ctx, 'sawtooth', frequency, filter, time, finish, 8);
  } else oscillator(ctx, 'triangle', frequency, filter, time, finish);
}

function playMidi(ctx, data, onEnd = () => {}) {
  let song;
  try { song = decode(data); } catch (error) { console.error(error); onEnd(0); return; }
  if (!ctx) { onEnd(0); return; }
  const start = () => {
    const tempos = song.events.filter(event => event.kind === 'T');
    const notes = song.events.filter(event => event.kind === 'N').map(event => ({
      event,
      at: secondsAt(event.tick, tempos, song.division),
      length: Math.max(.025, secondsAt(event.tick + event.duration, tempos, song.division) - secondsAt(event.tick, tempos, song.division)),
    }));
    const master = ctx.createGain(), delay = ctx.createDelay(.4), feedback = ctx.createGain(), wet = ctx.createGain();
    master.gain.value = .8;
    delay.delayTime.value = .16;
    feedback.gain.value = .18;
    wet.gain.value = .1;
    master.connect(ctx.destination);
    master.connect(delay);
    delay.connect(feedback);
    feedback.connect(delay);
    delay.connect(wet);
    wet.connect(ctx.destination);
    const channels = Array.from({ length: 16 }, (_, number) => ({ program: PROGRAM[number] || 0, volume: 100, pan: 64, expression: 127, bend: 8192 }));
    const base = ctx.currentTime + .08, buffer = noise(ctx), lookAhead = 2, interval = 80;
    let cursor = 0;
    const end = Math.max(secondsAt(song.endTick, tempos, song.division), ...notes.map(note => note.at + note.length));
    const pump = () => {
      const limit = ctx.currentTime - base + lookAhead;
      while (cursor < notes.length && notes[cursor].at <= limit) {
        const note = notes[cursor++];
        playNote(ctx, buffer, master, channels[note.event.channel], note.event, base + note.at, note.length);
      }
      if (cursor === notes.length) clearInterval(timer);
    };
    let timer;
    pump();
    timer = setInterval(pump, interval);
    stopFn = () => { clearInterval(timer); try { master.disconnect(); } catch (e) {} };
    onEnd(end);
  };
  let stopFn = () => {};
  let started = 0;
  const safeStart = () => {
    if (started) return;
    started = 1;
    start();
  };
  if (ctx.state === 'suspended') {
    ctx.resume().then(safeStart).catch(() => {});
    const onStateChange = () => {
      if (ctx.state === 'running') {
        ctx.removeEventListener('statechange', onStateChange);
        safeStart();
      }
    };
    ctx.addEventListener('statechange', onStateChange);
  } else {
    safeStart();
  }
  return { stop: () => { if (typeof stopFn === 'function') stopFn(); } };
}
